  if (compositionKind === "subtractive") {
    const incomingSet = new Set(uniqueIncoming);
    return uniquePrevious.filter((value) => !incomingSet.has(value));
  }
  const incomingSet = new Set(uniqueIncoming);
  return uniquePrevious.filter((value) => incomingSet.has(value));
}
